SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_1243
WHERE (rt.role IN ('actor','actress','cinematographer','composer','costume designer','director','editor','miscellaneous crew','producer','production designer','writer')) AND (pi.info ILIKE '%21%') AND (it1.id IN ('16')) AND (mi1.info ILIKE '%est%') AND (it2.id IN ('23')) AND (kt.kind IN ('episode','movie','tv mini series','tv movie','tv series','video game','video movie'));